"use client";

import { useState } from "react";
import { signIn } from "next-auth/react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from "@/components/ui/card";
import { Loader2 } from "lucide-react";
import { toast } from "sonner";

export default function SignupPage() {
  const [isLoading, setIsLoading] = useState(false);
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");

  const handleSignup = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);

    try {
      const res = await fetch("/api/auth/signup", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          name,
          email,
          password,
        }),
      });

      if (res.ok) {
        toast.success("Account created! Logging you in...");
        // Auto login after signup
        await signIn("credentials", {
          email,
          password,
          redirect: true,
          callbackUrl: "/dashboard",
        });
      } else {
        const data = await res.json();
        toast.error(data.message || "Something went wrong");
      }
    } catch {
      toast.error("Something went wrong");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-black p-4">
      <div className="absolute inset-0 bg-[url('/grid.png')] bg-[size:60px_60px] opacity-10 pointer-events-none" />

      <Card className="w-full max-w-md bg-black/50 backdrop-blur-xl border-white/10 text-white">
        <CardHeader className="space-y-1">
          <CardTitle className="text-2xl font-bold font-mono">Create an account</CardTitle>
          <CardDescription className="font-mono text-gray-400">
            Join the Fluxora community
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <form onSubmit={handleSignup} className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="name">Name</Label>
              <Input
                id="name"
                type="text"
                placeholder="John Doe"
                value={name}
                onChange={(e) => setName(e.target.value)}
                required
                className="bg-white/5 border-white/10 text-white placeholder:text-gray-500"
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="email">Email</Label>
              <Input
                id="email"
                type="email"
                placeholder="m@example.com"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required
                className="bg-white/5 border-white/10 text-white placeholder:text-gray-500"
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="password">Password</Label>
              <Input
                id="password"
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                required
                className="bg-white/5 border-white/10 text-white"
              />
            </div>
            <Button 
              type="submit" 
              className="w-full bg-primary hover:bg-primary/90 text-black font-bold font-mono"
              disabled={isLoading}
            >
              {isLoading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Sign Up
            </Button>
          </form>
        </CardContent>
        <CardFooter>
          <div className="text-sm text-gray-400 font-mono w-full text-center">
            Already have an account?{" "}
            <Link href="/login" className="text-primary hover:underline">
              Sign in
            </Link>
          </div>
        </CardFooter>
      </Card>
    </div>
  );
}

import { notFound } from "next/navigation"
import { prisma } from "@/lib/prisma"
import WorkflowGrid from "@/components/workflow/WorkflowGrid"
import { Metadata } from "next"
import { Pagination } from "@/components/ui/pagination"

const ITEMS_PER_PAGE = 12

export async function generateMetadata({ params }: { params: { slug: string } }): Promise<Metadata> {
  const category = await prisma.category.findUnique({
    where: { slug: params.slug },
  })

  if (!category) {
    return {
      title: "Category Not Found",
    }
  }

  const categoryDescription = category.description || `Browse ${category.name} n8n workflow templates - production-ready automation workflows`
  const pageUrl = `https://www.flowkit.in/category/${category.slug}`

  // Generate dynamic OG image
  const ogImageParams = new URLSearchParams({
    title: `${category.icon} ${category.name} Workflows`,
    description: categoryDescription.slice(0, 100),
    type: 'category',
  })
  const ogImage = `https://www.flowkit.in/api/og?${ogImageParams.toString()}`

  return {
    title: `${category.name} n8n Workflows | FlowKit`,
    description: categoryDescription,
    keywords: `${category.name} workflows, ${category.name} n8n templates, ${category.name} automation, n8n ${category.name.toLowerCase()}`,
    openGraph: {
      title: `${category.name} n8n Workflows | FlowKit`,
      description: categoryDescription,
      url: pageUrl,
      type: 'website',
      images: [
        {
          url: ogImage,
          width: 1200,
          height: 630,
          alt: `${category.name} Workflows`,
        },
      ],
    },
    twitter: {
      card: 'summary_large_image',
      title: `${category.name} n8n Workflows | FlowKit`,
      description: categoryDescription,
      images: [ogImage],
      creator: '@flowkit_in',
    },
    alternates: {
      canonical: pageUrl,
    },
  }
}

export default async function CategoryPage({ 
  params,
  searchParams,
}: { 
  params: { slug: string }
  searchParams: { page?: string }
}) {
  const currentPage = Number(searchParams.page) || 1
  const skip = (currentPage - 1) * ITEMS_PER_PAGE

  const category = await prisma.category.findUnique({
    where: { slug: params.slug },
    include: {
      _count: {
        select: { workflows: true },
      },
    },
  })

  if (!category) {
    notFound()
  }

  // Parallel queries for better performance
  const [totalCount, workflows] = await Promise.all([
    prisma.workflow.count({
      where: {
        published: true,
        categories: {
          some: {
            categoryId: category.id,
          },
        },
      },
    }),
    prisma.workflow.findMany({
      where: {
        published: true,
        categories: {
          some: {
            categoryId: category.id,
          },
        },
      },
      select: { id: true },
      orderBy: { createdAt: "desc" },
      take: ITEMS_PER_PAGE,
      skip: skip,
    }),
  ])

  // Step 2: Fetch full details for the IDs
  const workflowsData = await prisma.workflow.findMany({
    where: {
      id: { in: workflows.map((w) => w.id) },
    },
    select: {
      id: true,
      slug: true,
      name: true,
      description: true,
      icon: true,
      thumbnail: true,
      difficulty: true,
      featured: true,
      indiaBadge: true,
      nodeCount: true,
      views: true,
      downloads: true,
      createdAt: true,

      categories: {
        select: {
          category: {
            select: {
              id: true,
              name: true,
              slug: true,
              icon: true,
              color: true,
            },
          },
        },
      },
      tags: {
        select: {
          tag: {
            select: {
              id: true,
              name: true,
              slug: true,
            },
          },
        },
      },
    },
  })

  // Re-order workflows to match the sorted IDs
  const workflowsWithDetails = workflows.map((w) => 
    workflowsData.find((wd) => wd.id === w.id)!
  )

  const totalPages = Math.ceil(totalCount / ITEMS_PER_PAGE)

  // Transform to match expected type
  const transformedWorkflows = workflowsWithDetails.map((workflow) => ({
    ...workflow,
    videoUrl: null,
    workflowJson: {},
    useCases: [],
    setupSteps: [],
    credentialsRequired: [],
    nodes: [],
    published: true,
    updatedAt: workflow.createdAt,
    publishedAt: workflow.createdAt,
    categories: workflow.categories.map((cat) => ({
      category: {
        ...cat.category,
        description: null,
        order: 0,
        createdAt: new Date(),
        updatedAt: new Date(),
      },
    })),
    tags: workflow.tags.map((t) => ({
      tag: {
        ...t.tag,
        createdAt: new Date(),
      },
    })),
  }))

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
      <div className="space-y-8">
        {/* Category Header */}
        <div className="text-center space-y-4 border-b-2 pb-6">
          <div className="text-6xl">{category.icon}</div>
          <h1 className="text-4xl font-bold font-mono uppercase">{category.name}</h1>
          {category.description && (
            <p className="text-xl text-muted-foreground max-w-2xl mx-auto font-mono">
              {category.description}
            </p>
          )}
          <p className="text-muted-foreground font-mono">
            {totalCount} {totalCount === 1 ? "workflow" : "workflows"}
          </p>
        </div>

        {/* Workflows Grid */}
        {/* eslint-disable-next-line @typescript-eslint/no-explicit-any */}
        <WorkflowGrid
          workflows={transformedWorkflows as any}
          emptyMessage="No workflows in this category yet"
        />

        {/* Pagination */}
        <Pagination
          currentPage={currentPage}
          totalPages={totalPages}
          baseUrl={`/category/${params.slug}`}
          totalItems={totalCount}
          itemsPerPage={ITEMS_PER_PAGE}
        />
      </div>
    </div>
  )
}

