        <motion.div
          whileHover={{ y: -5, scale: 1.01 }}
          className={cn(
            "relative p-8 rounded-3xl border backdrop-blur-xl transition-all duration-500",
            "bg-black/40 hover:bg-black/60",
            item.border,
            item.glow
