            </div>
            <h3 className="text-2xl md:text-3xl font-bold font-mono uppercase tracking-tighter text-white">
              {item.title}
            </h3>
          </div>

          <p className="text-lg text-muted-foreground mb-8 leading-relaxed font-light">
            {item.description}
