                          />
                        </div>
                      ))}
                    </div>
                  </div>
                </CardContent>
              </Card>
            ))}

            <Button
              variant="outline"
              onClick={handleAddStep}
              className="w-full font-mono gap-2"
            >
              <Plus className="h-4 w-4" />
