import { NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';

export async function GET(req: Request) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user?.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const user = await prisma.user.findUnique({
      where: {
        id: session.user.id,
      },
      select: {
        id: true,
        email: true,
        name: true,
        image: true,
        bio: true,
        username: true,
        location: true,
        websiteUrl: true,
        twitterHandle: true,
        githubUrl: true,
        linkedinUrl: true,
      }
    });

    if (!user) {
      return NextResponse.json({ error: 'User not found' }, { status: 404 });
    }

    return NextResponse.json({ success: true, user });

  } catch (error) {
    console.error('[GET_SETTINGS]', error);
    return NextResponse.json({ error: 'Failed to fetch settings' }, { status: 500 });
  }
}

export async function PATCH(req: Request) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user?.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const body = await req.json();
    const { name, bio, location, websiteUrl, twitterHandle, githubUrl, linkedinUrl, username } = body;

    // Check username uniqueness if changing
    if (username) {
      const existingUser = await prisma.user.findFirst({
        where: {
          username,
          NOT: {
            id: session.user.id
          }
        }
      });
      if (existingUser) {
        return NextResponse.json({ error: 'Username already taken' }, { status: 400 });
      }
    }

    const updatedUser = await prisma.user.update({
      where: {
        id: session.user.id,
      },
      data: {
        name,
        bio,
        location,
        websiteUrl,
        twitterHandle,
        githubUrl,
        linkedinUrl,
        username,
      },
    });

    return NextResponse.json({ success: true, user: updatedUser });

  } catch (error) {
    console.error('[PATCH_SETTINGS]', error);
    return NextResponse.json({ error: 'Failed to update settings' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server"
import { prisma } from "@/lib/prisma"
import { sendAccessCodeEmail } from "@/lib/email"

// In-memory stores for rate limiting
// Note: In a serverless environment (like Vercel), these might reset on cold starts.
// For production scale, use Redis.
const otpCooldown = new Map<string, number>();
const ipRequestCounts = new Map<string, { count: number, resetTime: number }>();

const COOLDOWN_DURATION = 60 * 1000; // 60 seconds
const RATE_LIMIT_WINDOW = 60 * 60 * 1000; // 1 hour
const MAX_REQUESTS_PER_WINDOW = 3;

function generateAccessCode(): string {
  return Math.floor(100000 + Math.random() * 900000).toString()
}

function getIp(request: NextRequest): string {
  const forwardedFor = request.headers.get("x-forwarded-for");
  if (forwardedFor) {
    return forwardedFor.split(",")[0].trim();
  }
  return "unknown";
}

export async function POST(request: NextRequest) {
  try {
    const { email } = await request.json()
    const ip = getIp(request);

    if (!email || !email.includes("@")) {
      return NextResponse.json(
        { error: "Valid email is required" },
        { status: 400 }
      )
    }

    const normalizedEmail = email.toLowerCase().trim()
    const now = Date.now();

    // 1. Check Email Cooldown (60s)
    const lastRequestTime = otpCooldown.get(normalizedEmail);
    if (lastRequestTime && now - lastRequestTime < COOLDOWN_DURATION) {
      const remainingSeconds = Math.ceil((COOLDOWN_DURATION - (now - lastRequestTime)) / 1000);
      return NextResponse.json(
        { error: `Please wait ${remainingSeconds} seconds before requesting another code.` },
        { status: 429 }
      )
    }

    // 2. Check IP Rate Limit (3 requests per hour)
    const ipData = ipRequestCounts.get(ip);
    if (ipData) {
      if (now > ipData.resetTime) {
        // Reset window if expired
        ipRequestCounts.set(ip, { count: 1, resetTime: now + RATE_LIMIT_WINDOW });
      } else if (ipData.count >= MAX_REQUESTS_PER_WINDOW) {
        return NextResponse.json(
          { error: "Too many requests. Please try again later." },
          { status: 429 }
        )
      } else {
        // Increment count
        ipData.count++;
        ipRequestCounts.set(ip, ipData);
      }
    } else {
      // First request from this IP
      ipRequestCounts.set(ip, { count: 1, resetTime: now + RATE_LIMIT_WINDOW });
    }

    // Update cooldown for this email
    otpCooldown.set(normalizedEmail, now);

    // Check if email already exists
    let waitlistEntry = await prisma.waitlist.findUnique({
      where: { email: normalizedEmail },
    })

    let accessCode: string

    if (waitlistEntry) {
      // User already signed up, resend their existing code
      accessCode = waitlistEntry.accessCode

      // Update updatedAt to reflect new request (useful for expiry checks)
      await prisma.waitlist.update({
        where: { id: waitlistEntry.id },
        data: { updatedAt: new Date() }
      });
    } else {
      // Generate new access code
      accessCode = generateAccessCode()

      // Ensure access code is unique
      let existingCode = await prisma.waitlist.findUnique({
        where: { accessCode },
      })

      while (existingCode) {
        accessCode = generateAccessCode()
        existingCode = await prisma.waitlist.findUnique({
          where: { accessCode },
        })
      }

      // Create new waitlist entry
      waitlistEntry = await prisma.waitlist.create({
        data: {
          email: normalizedEmail,
          accessCode,
        },
      })
    }

    // Send access code email with retry logic
    try {
      const emailResult = await sendAccessCodeEmail(normalizedEmail, accessCode);
      console.log(`✅ Access code email sent successfully to ${normalizedEmail} on attempt ${emailResult.attempt}, ID: ${emailResult.id}`);

      return NextResponse.json({
        success: true,
        message: "Access code sent to your email",
      });
    } catch (emailError: any) {
      console.error(`❌ Failed to send email to ${normalizedEmail} after all retries:`, emailError);

      // Email failed but user is in waitlist, they can try again
      return NextResponse.json({
        success: false,
        error: "Failed to send email. Please try again in a moment.",
      }, { status: 500 });
    }
  } catch (error) {
    console.error("Waitlist signup error:", error)
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 }
    )
  }
}

import { NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { prisma } from "@/lib/prisma";

export async function GET(
    req: Request,
    { params }: { params: { id: string } }
) {
    try {
        const { searchParams } = new URL(req.url);
        const page = parseInt(searchParams.get("page") || "1");
        const limit = parseInt(searchParams.get("limit") || "5");
        const skip = (page - 1) * limit;

        const [comments, total] = await prisma.$transaction([
            prisma.comment.findMany({
                where: {
                    workflowId: params.id,
                    parentId: null,
                },
                include: {
                    user: {
                        select: {
                            name: true,
                            image: true,
                        },
                    },
                    replies: {
                        include: {
                            user: {
                                select: {
                                    name: true,
                                    image: true,
                                },
                            },
                        },
                        orderBy: {
                            createdAt: "asc",
                        },
                    },
                },
                orderBy: {
                    createdAt: "desc",
                },
                skip,
                take: limit,
            }),
            prisma.comment.count({
                where: {
                    workflowId: params.id,
                    parentId: null,
                },
            }),
        ]);

        return NextResponse.json({
            comments,
            pagination: {
                page,
                limit,
                total,
                totalPages: Math.ceil(total / limit),
            },
        });
    } catch (error) {
        return NextResponse.json(
            { message: "Internal server error" },
            { status: 500 }
        );
    }
}

export async function POST(
    req: Request,
    { params }: { params: { id: string } }
) {
    try {
        const session = await getServerSession(authOptions);

        if (!session) {
            return NextResponse.json(
                { message: "Unauthorized" },
                { status: 401 }
            );
        }

        const { content, parentId } = await req.json();

        if (!content) {
            return NextResponse.json(
                { message: "Content is required" },
                { status: 400 }
            );
        }

        const comment = await prisma.comment.create({
            data: {
                content,
                workflowId: params.id,
                userId: (session.user as any).id,
                parentId: parentId || null,
            },
            include: {
                user: {
                    select: {
                        name: true,
                        image: true,
                    },
                },
            },
        });

        return NextResponse.json(comment);
    } catch (error) {
        return NextResponse.json(
            { message: "Internal server error" },
            { status: 500 }
        );
    }
}

import { NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { prisma } from "@/lib/prisma";

export async function POST(
    req: Request,
    { params }: { params: { id: string } }
) {
    try {
        const session = await getServerSession(authOptions);

        if (!session) {
            return NextResponse.json(
                { message: "Unauthorized" },
                { status: 401 }
            );
        }

        const userId = (session.user as any).id;
        const workflowId = params.id;

        // Check if already saved
        const existing = await prisma.savedWorkflow.findUnique({
            where: {
                userId_workflowId: {
                    userId,
                    workflowId,
                },
            },
        });

        if (existing) {
            // Unsave
            await prisma.savedWorkflow.delete({
                where: {
                    userId_workflowId: {
                        userId,
                        workflowId,
                    },
                },
            });
            return NextResponse.json({ saved: false });
        } else {
            // Save
            await prisma.savedWorkflow.create({
                data: {
                    userId,
                    workflowId,
                },
            });
            return NextResponse.json({ saved: true });
        }
    } catch {
        return NextResponse.json(
            { message: "Internal server error" },
            { status: 500 }
        );
    }
}

import { NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { prisma } from "@/lib/prisma";

export async function POST(
    req: Request,
    { params }: { params: { id: string } }
) {
    try {
        const session = await getServerSession(authOptions);

        if (!session) {
            return NextResponse.json(
                { message: "Unauthorized" },
                { status: 401 }
            );
        }

        const { type } = await req.json();

        if (!["UPVOTE", "DOWNVOTE"].includes(type)) {
            return NextResponse.json(
                { message: "Invalid vote type" },
                { status: 400 }
            );
        }

        const userId = (session.user as any).id;
        const workflowId = params.id;

        // Check if vote exists
        const existingVote = await prisma.vote.findUnique({
            where: {
                userId_workflowId: {
                    userId,
                    workflowId,
                },
            },
        });

        if (existingVote) {
            if (existingVote.type === type) {
                // Toggle off if same vote type
                await prisma.vote.delete({
                    where: {
                        id: existingVote.id,
                    },
                });
                return NextResponse.json({ message: "Vote removed", vote: null });
            } else {
                // Update vote type if different
                const vote = await prisma.vote.update({
                    where: {
                        id: existingVote.id,
                    },
                    data: {
                        type,
                    },
                });
                return NextResponse.json(vote);
            }
        } else {
            // Create new vote
            const vote = await prisma.vote.create({
                data: {
                    type,
                    userId,
                    workflowId,
                },
            });
            return NextResponse.json(vote);
        }
    } catch (error) {
        console.error("Vote error:", error);
        return NextResponse.json(
            { message: "Internal server error" },
            { status: 500 }
        );
    }
}

import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
