export default async function DashboardPage() {
  const session = await getServerSession(authOptions);

  if (!session) {
    redirect("/login");
  }

  if ((session.user as any).role === "ADMIN" || (session.user as any).role === "SUPER_ADMIN") {
    redirect("/admin");
  }

  const savedWorkflows = await prisma.savedWorkflow.findMany({
    where: {
      userId: (session.user as any).id,
    },
    include: {
      workflow: {
        include: {
          categories: {
            include: { category: true },
          },
          tags: {
            include: { tag: true },
          },
        },
      },
    },
    orderBy: {
      createdAt: "desc",
    },
  });

  // Transform for grid
  const workflows = savedWorkflows.map((sw: any) => ({
    ...sw.workflow,
    categories: sw.workflow.categories.map((c: any) => ({ category: c.category })),
    tags: sw.workflow.tags.map((t: any) => ({ tag: t.tag })),
  }));

  const purchases = await prisma.purchase.findMany({
    where: {
      userId: (session.user as any).id,
    },
    include: {
      workflow: true,
    },
    orderBy: {
      createdAt: "desc",
    },
  });

  return (
    <div className="min-h-screen bg-black">
      <StickyNavbar />

