export default function AccessGate() {
  const [step, setStep] = useState<"email" | "code">("email")
  const [email, setEmail] = useState("")
  const [accessCode, setAccessCode] = useState("")
  const [isLoading, setIsLoading] = useState(false)
  const [waitlistCount, setWaitlistCount] = useState(0)
  const [accessedCount, setAccessedCount] = useState(0)
  const [isMobile, setIsMobile] = useState(false)
  const [mounted, setMounted] = useState(false)

  useEffect(() => {
    setMounted(true)

    // Check if user has valid access in localStorage (persists across tabs)
    const hasAccess = localStorage.getItem("flowkit_access")
    if (hasAccess === "true") {
      window.location.reload()
    }

    // Detect mobile
    const checkMobile = () => {
      setIsMobile(window.innerWidth < 1024)
    }
    checkMobile()
    window.addEventListener("resize", checkMobile)

    // Fetch waitlist stats
    fetch("/api/waitlist/count")
      .then(res => res.json())
      .then(data => {
        setWaitlistCount(data.count || 0)
        setAccessedCount(Math.floor((data.count || 0) * 0.65))
      })
      .catch(() => {})

    return () => window.removeEventListener("resize", checkMobile)
  }, [])

  const handleEmailSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    if (!email || !email.includes("@")) {
      toast.error("Please enter a valid email address")
      return
    }

    setIsLoading(true)

    try {
      const response = await fetch("/api/waitlist/signup", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email }),
      })

      const data = await response.json()

      if (!response.ok) {
        throw new Error(data.error || "Something went wrong")
      }

      toast.success("✓ Check your inbox! Access code arriving now...")
      setStep("code")
      setWaitlistCount(prev => prev + 1)
    } catch (error: any) {
      toast.error(error.message || "Failed to send access code")
    } finally {
      setIsLoading(false)
    }
  }

  const handleCodeSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

