      const response = await fetch("/api/waitlist/verify", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, accessCode }),
      })

      const data = await response.json()

      if (!response.ok) {
        throw new Error(data.error || "Invalid access code")
      }

      toast.success("Access granted! Welcome to Fluxora.")
      localStorage.setItem("flowkit_access", "true")

      setTimeout(() => {
        window.location.reload()
      }, 500)
    } catch (error: any) {
      toast.error(error.message || "Invalid access code")
    } finally {
      setIsLoading(false)
    }
  }

  const handleCodeInput = (value: string) => {
    const sanitized = value.replace(/\D/g, "").slice(0, 6)
    setAccessCode(sanitized)
  }

  if (!mounted) return null

  return (
    <div className="fixed inset-0 w-screen h-screen z-[9999] bg-black overflow-hidden">
      {/* Animated Grid Background */}
      <div
        className="absolute inset-0 pointer-events-none"
        style={{
          backgroundImage: 'url(/grid.png)',
