"use client";

import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";
import { updateAIProvider } from "@/app/admin/settings/actions";
import { AIProvider } from "@/lib/ai-provider";
import { Loader2 } from "lucide-react";

interface AISettingsProps {
  initialProvider: AIProvider;
}

export function AISettings({ initialProvider }: AISettingsProps) {
  const [provider, setProvider] = useState<AIProvider>(initialProvider);
  const [isSaving, setIsSaving] = useState(false);

  const handleSave = async () => {
    setIsSaving(true);
    try {
      const result = await updateAIProvider(provider);
      if (result.success) {
        toast.success("AI Provider updated successfully");
      } else {
        toast.error("Failed to update AI provider");
      }
    } catch (error) {
      toast.error("An error occurred");
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <Card>
      <CardHeader>
        <CardTitle>AI Configuration</CardTitle>
      </CardHeader>
      <CardContent className="space-y-6">
        <div className="space-y-4">
          <div className="space-y-2">
            <Label>AI Provider</Label>
            <p className="text-sm text-gray-400">
              Select the primary AI provider for generating workflows and content.
            </p>
          </div>

          <RadioGroup 
            value={provider} 
            onValueChange={(value: string) => setProvider(value as AIProvider)}
            className="grid grid-cols-1 md:grid-cols-2 gap-4"
          >
            <div className={`flex items-center space-x-2 border rounded-lg p-4 cursor-pointer transition-colors ${provider === 'groq' ? 'border-primary bg-primary/10' : 'border-border hover:bg-accent/50'}`}>
              <RadioGroupItem value="groq" id="groq" />
              <Label htmlFor="groq" className="flex-1 cursor-pointer">
                <div className="font-semibold">Groq (Llama 3)</div>
                <div className="text-xs text-gray-400">Fast inference, recommended for text generation</div>
              </Label>
            </div>

            <div className={`flex items-center space-x-2 border rounded-lg p-4 cursor-pointer transition-colors ${provider === 'gemini' ? 'border-primary bg-primary/10' : 'border-border hover:bg-accent/50'}`}>
              <RadioGroupItem value="gemini" id="gemini" />
              <Label htmlFor="gemini" className="flex-1 cursor-pointer">
                <div className="font-semibold">Google Gemini</div>
                <div className="text-xs text-gray-400">Multimodal capabilities, required for image generation</div>
              </Label>
            </div>
          </RadioGroup>
        </div>

        <div className="flex justify-end">
          <Button onClick={handleSave} disabled={isSaving || provider === initialProvider}>
            {isSaving && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
            Save Changes
          </Button>
        </div>
      </CardContent>
    </Card>
  );
}

"use client"

import { useState, useEffect } from "react"
import { useRouter } from "next/navigation"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Textarea } from "@/components/ui/textarea"
import { Checkbox } from "@/components/ui/checkbox"
import { Badge } from "@/components/ui/badge"
import { Card } from "@/components/ui/card"
import { Loader2, Plus, X, Sparkles, Image as ImageIcon, Wand2 } from "lucide-react"
import { toast } from "sonner"
import { BundleFormData } from "@/types"
import { CloudinaryImageUpload } from "@/components/admin/CloudinaryImageUpload"

interface BundleFormProps {
  bundle?: any // Existing bundle for editing
}

export function BundleForm({ bundle }: BundleFormProps) {
  const router = useRouter()
  const isEditing = !!bundle

  // Form state
  const [formData, setFormData] = useState<BundleFormData>({
    name: bundle?.name || "",
    slug: bundle?.slug || "",
    description: bundle?.description || "",
    objective: bundle?.objective || "",
    icon: bundle?.icon || "",
    thumbnail: bundle?.thumbnail || "",
    aiImagePrompt: bundle?.aiImagePrompt || "",
    color: bundle?.color || "#667eea",
    featured: bundle?.featured || false,
    order: bundle?.order || 0,
    benefits: bundle?.benefits ? (Array.isArray(bundle.benefits) ? bundle.benefits : []) : [],
    targetAudience: bundle?.targetAudience || "",
    estimatedTime: bundle?.estimatedTime || "",
    workflowIds: bundle?.workflows?.map((w: any) => w.workflow.id) || [],
    published: bundle?.published || false,
  })

  const [newBenefit, setNewBenefit] = useState("")
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [isGeneratingPrompt, setIsGeneratingPrompt] = useState(false)
  const [isAutoFilling, setIsAutoFilling] = useState(false)
  const [workflows, setWorkflows] = useState<any[]>([])
  const [isLoadingWorkflows, setIsLoadingWorkflows] = useState(true)

  // Load workflows
  useEffect(() => {
    async function loadWorkflows() {
      try {
        const response = await fetch("/api/workflows?published=true&limit=100")
        const data = await response.json()
        setWorkflows(data.workflows || [])
      } catch (error) {
        console.error("Failed to load workflows:", error)
        toast.error("Failed to load workflows")
      } finally {
        setIsLoadingWorkflows(false)
      }
    }
    loadWorkflows()
  }, [])

  // Auto-generate slug from name
  useEffect(() => {
    if (!isEditing && formData.name) {
      const slug = formData.name
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, "-")
        .replace(/(^-|-$)/g, "")
      setFormData((prev) => ({ ...prev, slug }))
    }
  }, [formData.name, isEditing])

  const handleAddBenefit = () => {
    if (newBenefit.trim()) {
      setFormData((prev) => ({
        ...prev,
        benefits: [...prev.benefits, newBenefit.trim()],
      }))
      setNewBenefit("")
    }
  }

  const handleRemoveBenefit = (index: number) => {
    setFormData((prev) => ({
      ...prev,
      benefits: prev.benefits.filter((_, i) => i !== index),
    }))
  }

  const toggleWorkflow = (workflowId: string) => {
    setFormData((prev) => {
      const isSelected = prev.workflowIds.includes(workflowId)
      return {
        ...prev,
        workflowIds: isSelected
          ? prev.workflowIds.filter((id) => id !== workflowId)
          : [...prev.workflowIds, workflowId],
      }
    })
  }

  const handleThumbnailUpload = (url: string) => {
    setFormData((prev) => ({ ...prev, thumbnail: url }))
    toast.success("Image uploaded successfully!")
  }

  const handleGenerateImagePrompt = async () => {
    if (!formData.name) {
      toast.error("Please enter a bundle name first")
      return
    }

    setIsGeneratingPrompt(true)
    try {
      const response = await fetch(`/api/bundles/${bundle?.id || "temp"}/generate-image`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          bundleName: formData.name,
          bundleDescription: formData.description,
          bundleObjective: formData.objective,
          workflowCount: formData.workflowIds.length,
        }),
      })

      if (!response.ok) throw new Error("Failed to generate prompt")

      const data = await response.json()
      const promptText = JSON.stringify(data.prompt, null, 2)
      setFormData((prev) => ({ ...prev, aiImagePrompt: promptText }))
      toast.success("AI image prompt generated!")
    } catch (error) {
      toast.error("Failed to generate AI prompt")
    } finally {
      setIsGeneratingPrompt(false)
    }
  }

  const handleAutoFill = async () => {
    if (formData.workflowIds.length === 0) {
      toast.error("Please select at least one workflow first")
      return
    }

    setIsAutoFilling(true)
    try {
      // Get selected workflows data
      const selectedWorkflows = workflows.filter((w) => formData.workflowIds.includes(w.id))

      const response = await fetch("/api/bundles/autofill", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ workflows: selectedWorkflows }),
      })

      if (!response.ok) {
        throw new Error("Failed to generate bundle details")
      }

      const { data } = await response.json()

      setFormData((prev) => ({
        ...prev,
        name: data.name || prev.name,
        description: data.description || prev.description,
        objective: data.objective || prev.objective,
        benefits: data.benefits || prev.benefits,
        targetAudience: data.targetAudience || prev.targetAudience,
        estimatedTime: data.estimatedTime || prev.estimatedTime,
        icon: data.icon || prev.icon,
      }))

      toast.success("✨ AI Auto-filled bundle details! Review and adjust as needed.")
    } catch (error) {
      console.error("Auto-fill error:", error)
      toast.error("Failed to auto-fill details. Please try again.")
    } finally {
      setIsAutoFilling(false)
    }
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    if (!formData.name || !formData.slug || !formData.description || !formData.objective) {
      toast.error("Please fill in all required fields")
      return
    }

    if (formData.workflowIds.length === 0) {
      toast.error("Please select at least one workflow")
      return
    }

    setIsSubmitting(true)

    try {
      const url = isEditing ? `/api/bundles/${bundle.id}` : "/api/bundles"
      const method = isEditing ? "PUT" : "POST"

      const response = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(formData),
      })

      if (!response.ok) {
        const data = await response.json()
        throw new Error(data.error || "Failed to save bundle")
      }

      toast.success(`Bundle ${isEditing ? "updated" : "created"} successfully!`)
      router.push("/admin/bundles")
      router.refresh()
    } catch (error) {
      console.error("Submit error:", error)
      toast.error(error instanceof Error ? error.message : "Failed to save bundle")
    } finally {
      setIsSubmitting(false)
    }
  }

  return (
    <form onSubmit={handleSubmit} className="space-y-6">
      {/* AI Auto-Fill Button */}
      <div className="flex justify-end">
        <Button
          type="button"
          onClick={handleAutoFill}
          disabled={isAutoFilling || formData.workflowIds.length === 0}
          variant="outline"
          className="gap-2"
        >
          {isAutoFilling ? (
            <>
              <Loader2 className="h-4 w-4 animate-spin" />
              Auto-filling...
            </>
          ) : (
            <>
              <Wand2 className="h-4 w-4" />
              AI Auto-Fill Details
            </>
          )}
        </Button>
      </div>

      {/* Basic Info */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div className="space-y-2">
          <Label htmlFor="name">Bundle Name *</Label>
          <Input
            id="name"
            value={formData.name}
            onChange={(e) => setFormData({ ...formData, name: e.target.value })}
            placeholder="E.g., E-commerce Complete Automation Bundle"
            required
          />
        </div>

        <div className="space-y-2">
          <Label htmlFor="slug">Slug *</Label>
          <Input
            id="slug"
            value={formData.slug}
            onChange={(e) => setFormData({ ...formData, slug: e.target.value })}
            placeholder="e-commerce-complete-automation-bundle"
            required
          />
        </div>
      </div>

      {/* Icon and Color */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="space-y-2">
          <Label htmlFor="icon">Icon (Emoji)</Label>
          <Input
            id="icon"
            value={formData.icon}
            onChange={(e) => setFormData({ ...formData, icon: e.target.value })}
            placeholder="📦"
            maxLength={2}
          />
        </div>

        <div className="space-y-2">
          <Label htmlFor="color">Theme Color</Label>
          <div className="flex gap-2">
            <Input
              id="color"
              type="color"
              value={formData.color}
              onChange={(e) => setFormData({ ...formData, color: e.target.value })}
              className="h-10 w-20"
            />
            <Input
              type="text"
              value={formData.color}
              onChange={(e) => setFormData({ ...formData, color: e.target.value })}
              placeholder="#667eea"
            />
          </div>
        </div>

        <div className="space-y-2">
          <Label htmlFor="order">Display Order</Label>
          <Input
            id="order"
            type="number"
            value={formData.order}
            onChange={(e) => setFormData({ ...formData, order: parseInt(e.target.value) || 0 })}
            min="0"
          />
        </div>
      </div>

      {/* Description */}
      <div className="space-y-2">
        <Label htmlFor="description">Description *</Label>
        <Textarea
          id="description"
          value={formData.description}
          onChange={(e) => setFormData({ ...formData, description: e.target.value })}
          placeholder="Brief description of the bundle..."
          rows={3}
          required
        />
      </div>

      {/* Objective */}
      <div className="space-y-2">
        <Label htmlFor="objective">Main Objective *</Label>
        <Textarea
          id="objective"
          value={formData.objective}
          onChange={(e) => setFormData({ ...formData, objective: e.target.value })}
          placeholder="What is the main goal of this bundle? E.g., 'Automate your entire e-commerce operations from order processing to customer support'"
          rows={2}
          required
        />
      </div>

      {/* Benefits */}
      <div className="space-y-2">
        <Label>Key Benefits</Label>
        <div className="flex gap-2">
          <Input
            value={newBenefit}
            onChange={(e) => setNewBenefit(e.target.value)}
            placeholder="Add a benefit..."
            onKeyPress={(e) => e.key === "Enter" && (e.preventDefault(), handleAddBenefit())}
          />
          <Button type="button" onClick={handleAddBenefit} variant="outline">
            <Plus className="h-4 w-4" />
          </Button>
        </div>
        <div className="flex flex-wrap gap-2 mt-2">
          {formData.benefits.map((benefit, index) => (
            <Badge key={index} variant="secondary" className="gap-1">
              {benefit}
              <X
                className="h-3 w-3 cursor-pointer"
                onClick={() => handleRemoveBenefit(index)}
              />
            </Badge>
          ))}
        </div>
      </div>

      {/* Target Audience & Estimated Time */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div className="space-y-2">
          <Label htmlFor="targetAudience">Target Audience</Label>
          <Input
            id="targetAudience"
            value={formData.targetAudience}
            onChange={(e) => setFormData({ ...formData, targetAudience: e.target.value })}
            placeholder="E.g., E-commerce store owners"
          />
        </div>

        <div className="space-y-2">
          <Label htmlFor="estimatedTime">Estimated Setup Time</Label>
          <Input
            id="estimatedTime"
            value={formData.estimatedTime}
            onChange={(e) => setFormData({ ...formData, estimatedTime: e.target.value })}
            placeholder="E.g., 30 minutes"
          />
        </div>
      </div>

      {/* AI Image Generation */}
      <div className="space-y-2">
        <div className="flex items-center justify-between">
          <Label htmlFor="aiImagePrompt">AI Image Prompt</Label>
          <Button
            type="button"
            onClick={handleGenerateImagePrompt}
            disabled={isGeneratingPrompt}
            variant="outline"
            size="sm"
          >
            {isGeneratingPrompt ? (
              <><Loader2 className="h-4 w-4 mr-2 animate-spin" />Generating...</>
            ) : (
              <><Sparkles className="h-4 w-4 mr-2" />Generate AI Prompt</>
            )}
          </Button>
        </div>
        <Textarea
          id="aiImagePrompt"
          value={formData.aiImagePrompt}
          onChange={(e) => setFormData({ ...formData, aiImagePrompt: e.target.value })}
          placeholder="AI-generated image prompt will appear here..."
          rows={6}
          className="font-mono text-sm"
        />
      </div>

      {/* Thumbnail Upload */}
      <div className="space-y-2">
        <CloudinaryImageUpload
          value={formData.thumbnail}
          onChange={handleThumbnailUpload}
          folder="flowkit-bundles"
          label="Bundle Thumbnail"
          description="Upload a thumbnail image for this bundle (max 10MB, JPG/PNG/WebP/GIF)"
        />
        <div className="mt-2">
          <Label htmlFor="thumbnailUrl">Or enter URL directly</Label>
          <Input
            id="thumbnailUrl"
            value={formData.thumbnail}
            onChange={(e) => setFormData({ ...formData, thumbnail: e.target.value })}
            placeholder="https://..."
            className="mt-1"
          />
        </div>
      </div>

      {/* Workflow Selection */}
      <div className="space-y-2">
        <Label>Select Workflows * ({formData.workflowIds.length} selected)</Label>
        {isLoadingWorkflows ? (
          <div className="flex items-center justify-center py-8">
            <Loader2 className="h-6 w-6 animate-spin" />
          </div>
        ) : (
          <Card className="p-4 max-h-96 overflow-y-auto">
            <div className="space-y-2">
              {workflows.map((workflow) => (
                <div
                  key={workflow.id}
                  className="flex items-center space-x-2 p-2 hover:bg-muted rounded"
                >
                  <Checkbox
                    id={`workflow-${workflow.id}`}
                    checked={formData.workflowIds.includes(workflow.id)}
                    onCheckedChange={() => toggleWorkflow(workflow.id)}
                  />
                  <Label
                    htmlFor={`workflow-${workflow.id}`}
                    className="flex items-center gap-2 flex-1 cursor-pointer"
                  >
                    {workflow.icon && <span>{workflow.icon}</span>}
                    <span className="text-sm">{workflow.name}</span>
                  </Label>
                </div>
              ))}
            </div>
          </Card>
        )}
      </div>

      {/* Flags */}
      <div className="flex gap-6">
        <div className="flex items-center space-x-2">
          <Checkbox
            id="featured"
            checked={formData.featured}
            onCheckedChange={(checked) =>
              setFormData((prev) => ({ ...prev, featured: !!checked }))
            }
          />
          <Label htmlFor="featured" className="cursor-pointer">
            Featured Bundle
          </Label>
        </div>

        <div className="flex items-center space-x-2">
          <Checkbox
            id="published"
            checked={formData.published}
            onCheckedChange={(checked) =>
              setFormData((prev) => ({ ...prev, published: !!checked }))
            }
          />
          <Label htmlFor="published" className="cursor-pointer">
            Published
          </Label>
        </div>
      </div>

      {/* Submit Buttons */}
      <div className="flex gap-4 pt-4">
        <Button type="submit" disabled={isSubmitting} className="flex-1">
          {isSubmitting ? (
            <>
              <Loader2 className="mr-2 h-4 w-4 animate-spin" />
              {isEditing ? "Updating..." : "Creating..."}
            </>
          ) : (
            <>{isEditing ? "Update Bundle" : "Create Bundle"}</>
          )}
        </Button>
        <Button
          type="button"
          variant="outline"
          onClick={() => router.back()}
          disabled={isSubmitting}
        >
          Cancel
        </Button>
      </div>
    </form>
  )
}

"use client";

import { useEffect, useRef, useState } from "react";
import { Label } from "@/components/ui/label";

interface RichTextEditorProps {
  value: string;
  onChange: (value: string) => void;
  label?: string;
  placeholder?: string;
  error?: string;
}

export function RichTextEditor({
  value,
  onChange,
  label,
  placeholder,
  error,
}: RichTextEditorProps) {
  const editorRef = useRef<any>(null);
  const [editorLoaded, setEditorLoaded] = useState(false);
  const { CKEditor, ClassicEditor } = editorRef.current || {};

  useEffect(() => {
    editorRef.current = {
      CKEditor: require("@ckeditor/ckeditor5-react").CKEditor,
      ClassicEditor: require("@ckeditor/ckeditor5-build-classic"),
    };
    setEditorLoaded(true);
  }, []);

  const editorConfiguration = {
    toolbar: [
      "heading",
      "|",
      "bold",
      "italic",
      "link",
      "bulletedList",
      "numberedList",
      "|",
      "blockQuote",
      "undo",
      "redo",
    ],
    placeholder: placeholder || "Enter content...",
  };

  return (
    <div className="space-y-2">
      {label && (
        <Label className="text-sm font-medium text-foreground">{label}</Label>
      )}
      <div
        className={`border rounded-md ${error ? "border-destructive" : "border-input"}`}
        style={{
          minHeight: "200px",
        }}
      >
        {editorLoaded ? (
          <CKEditor
            editor={ClassicEditor}
            data={value}
            onChange={(_event: any, editor: any) => {
              const data = editor.getData();
              onChange(data);
            }}
            config={editorConfiguration}
          />
        ) : (
          <div className="flex items-center justify-center h-[200px] text-muted-foreground">
            Loading editor...
          </div>
        )}
      </div>
      {error && <p className="text-sm text-destructive">{error}</p>}
      <style jsx global>{`
        .ck-editor__editable {
          min-height: 200px !important;
          background-color: transparent !important;
          color: inherit !important;
        }
        .ck.ck-toolbar {
          background-color: hsl(var(--muted)) !important;
          border-color: hsl(var(--border)) !important;
        }
        .ck.ck-button {
          color: hsl(var(--foreground)) !important;
        }
        .ck.ck-button:hover {
          background-color: hsl(var(--accent)) !important;
        }
        .ck.ck-button.ck-on {
          background-color: hsl(var(--accent)) !important;
        }
        .ck-content {
          color: hsl(var(--foreground)) !important;
        }
      `}</style>
    </div>
  );
}

"use client"

import { useEffect, useState } from "react"
import { useRouter } from "next/navigation"
import { useForm, SubmitHandler } from "react-hook-form"
import { zodResolver } from "@hookform/resolvers/zod"
import { Category, Tag, Workflow } from "@prisma/client"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Textarea } from "@/components/ui/textarea"
import { Label } from "@/components/ui/label"
import { Checkbox } from "@/components/ui/checkbox"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import { toast } from "sonner"
import { workflowFormSchema, WorkflowFormValues } from "@/lib/validations/workflow"
import { generateSlug } from "@/lib/utils"
import { parseWorkflowJSON } from "@/lib/gemini"
import { Plus, X, FileJson, Sparkles, Loader2, Copy, AlertCircle } from "lucide-react"
import { CloudinaryImageUpload } from "@/components/admin/CloudinaryImageUpload"
import { AIButton } from "@/components/admin/AIButton"
import { RichTextEditor } from "@/components/admin/RichTextEditor"

interface WorkflowFormProps {
  initialData?: Workflow & {
    categories: { category: Category }[]
    tags: { tag: Tag }[]
  } & {
    author?: string | null
    authorUrl?: string | null
  }
  categories: Category[]
  tags: Tag[]
}

export default function WorkflowForm({ initialData, categories, tags }: WorkflowFormProps) {
  const router = useRouter()
  const [isLoading, setIsLoading] = useState(false)
  const [isGeneratingThumbnail, setIsGeneratingThumbnail] = useState(false)
  const [isAutoFilling, setIsAutoFilling] = useState(false)
  const [thumbnailPrompt, setThumbnailPrompt] = useState<any>(null)
  const [showPromptDialog, setShowPromptDialog] = useState(false)
  const [duplicateWarning, setDuplicateWarning] = useState<{ name: string; slug: string } | null>(null)
  const [isCheckingDuplicate, setIsCheckingDuplicate] = useState(false)

  // Initialize form with default values
  const {
    register,
    handleSubmit,
    formState: { errors },
    setValue,
    watch,
  } = useForm<WorkflowFormValues>({
    resolver: zodResolver(workflowFormSchema) as any,
    defaultValues: initialData
      ? {
          name: initialData.name,
          slug: initialData.slug,
          description: initialData.description,
          icon: initialData.icon || "",
          thumbnail: initialData.thumbnail || "",
          videoUrl: initialData.videoUrl || "",
          documentLink: initialData.documentLink || "",
          difficulty: initialData.difficulty,
          featured: initialData.featured,
          indiaBadge: initialData.indiaBadge,
          nodeCount: initialData.nodeCount,
          categoryIds: initialData.categories.map((c) => c.category.id),
          tagNames: initialData.tags.map((t) => t.tag.name),
          credentialsRequired: initialData.credentialsRequired as string[],
          nodes: initialData.nodes as string[],
          useCases: initialData.useCases as string[],
          setupSteps: initialData.setupSteps as string[],
          workflowJson: JSON.stringify(initialData.workflowJson, null, 2),
          published: initialData.published,
          isPaid: initialData.isPaid || false,
          price: initialData.price || 0,
          author: initialData.author || "",
          authorUrl: initialData.authorUrl || "",
        }
      : {
          name: "",
          slug: "",
          description: "",
          icon: "",
          thumbnail: "",
          videoUrl: "",
          documentLink: "",
          difficulty: "BEGINNER",
          featured: false,
          indiaBadge: false,
          nodeCount: 0,
          categoryIds: [],
          tagNames: [],
          credentialsRequired: [],
          nodes: [],
          useCases: [""],
          setupSteps: [""],
          workflowJson: "{}",
          published: false,
          isPaid: false,
          price: 0,
          author: "",
          authorUrl: "",
        },
  })

  const watchName = watch("name")
  const watchCategoryIds = watch("categoryIds")
  const watchTagNames = watch("tagNames")
  const watchUseCases = watch("useCases")
  const watchSetupSteps = watch("setupSteps")
  const watchCredentials = watch("credentialsRequired")
  const watchNodes = watch("nodes")

  // Auto-generate slug from name
  useEffect(() => {
    if (watchName && !initialData) {
      setValue("slug", generateSlug(watchName))
    }
  }, [watchName, setValue, initialData])

  // Handle Cloudinary thumbnail upload
  const handleThumbnailUpload = (url: string, publicId?: string) => {
    setValue("thumbnail", url)
    toast.success("Image uploaded successfully!")
  }

  // Dynamic array helpers
  const addArrayItem = (field: "useCases" | "setupSteps" | "credentialsRequired" | "nodes") => {
    const currentValue = watch(field)
    setValue(field, [...currentValue, ""])
  }

  const removeArrayItem = (field: "useCases" | "setupSteps" | "credentialsRequired" | "nodes", index: number) => {
    const currentValue = watch(field)
    setValue(
      field,
      currentValue.filter((_, i) => i !== index)
    )
  }

  const updateArrayItem = (field: "useCases" | "setupSteps" | "credentialsRequired" | "nodes", index: number, value: string) => {
    const currentValue = watch(field)
    const newValue = [...currentValue]
    newValue[index] = value
    setValue(field, newValue)
  }

  // Category selection toggle
  const toggleCategory = (categoryId: string) => {
    const current = watchCategoryIds || []
    if (current.includes(categoryId)) {
      setValue(
        "categoryIds",
        current.filter((id) => id !== categoryId)
      )
    } else {
      setValue("categoryIds", [...current, categoryId])
    }
  }

  // Tag input
  const [tagInput, setTagInput] = useState("")
  const addTag = () => {
    if (tagInput.trim()) {
      const current = watchTagNames || []
      if (!current.includes(tagInput.trim())) {
        setValue("tagNames", [...current, tagInput.trim()])
      }
      setTagInput("")
    }
  }

  const removeTag = (tag: string) => {
    const current = watchTagNames || []
    setValue(
      "tagNames",
      current.filter((t) => t !== tag)
    )
  }

  // Parse JSON and auto-fill fields
  const handleParseJSON = () => {
    const jsonString = watch("workflowJson")

    try {
      const parsed = parseWorkflowJSON(jsonString)

      // Update form values
      setValue("nodeCount", parsed.nodeCount)
      setValue("nodes", parsed.nodes)
      setValue("credentialsRequired", parsed.credentialsRequired)

      toast.success(`Parsed ${parsed.nodeCount} nodes and ${parsed.credentialsRequired.length} credentials!`)
    } catch (error) {
      toast.error(error instanceof Error ? error.message : "Failed to parse JSON")
    }
  }

  // Generate AI thumbnail prompt
  const handleGenerateThumbnail = async () => {
    const name = watch("name")
    const jsonString = watch("workflowJson")

    if (!name || !jsonString) {
      toast.error("Please provide workflow name and JSON first")
      return
    }

    setIsGeneratingThumbnail(true)

    try {
      const response = await fetch("/api/ai/generate-thumbnail", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          workflowName: name,
          workflowJson: jsonString,
        }),
      })

      if (!response.ok) {
        const error = await response.json()
        throw new Error(error.error || "Failed to generate thumbnail prompt")
      }

      const data = await response.json()
      setThumbnailPrompt(data.prompt)
      setShowPromptDialog(true)
      toast.success("Thumbnail prompt generated! Copy it to use in AI Studio.")
    } catch (error) {
      console.error("Thumbnail prompt generation error:", error)
      toast.error(error instanceof Error ? error.message : "Failed to generate thumbnail prompt")
    } finally {
      setIsGeneratingThumbnail(false)
    }
  }

  // Copy prompt to clipboard
  const copyPromptToClipboard = () => {
    if (thumbnailPrompt) {
      navigator.clipboard.writeText(JSON.stringify(thumbnailPrompt, null, 2))
      toast.success("Prompt copied to clipboard!")
    }
  }

  // Complete Auto-fill - AI analyzes JSON and fills ALL fields
  const handleCompleteAutoFill = async () => {
    const jsonString = watch("workflowJson");

    if (!jsonString || jsonString.trim() === "{}") {
      toast.error("Please paste your workflow JSON first");
      return;
    }

    setIsAutoFilling(true);

    try {
      const response = await fetch("/api/ai/complete-autofill", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          workflowJson: jsonString,
        }),
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error || "Failed to auto-fill");
      }

      const { data } = await response.json();

      // Fill all fields with AI-generated data
      setValue("name", data.name);
      setValue("description", data.description);
      setValue("icon", data.icon);
      setValue("difficulty", data.difficulty);
      setValue("nodeCount", data.nodeCount);
      setValue("nodes", data.nodes || []);
      setValue("credentialsRequired", data.credentialsRequired || []);
      setValue("useCases", data.useCases || [""]);
      setValue("setupSteps", data.setupSteps || [""]);
      setValue("tagNames", data.tags || []);

      toast.success("🎉 All fields auto-filled successfully! Review and adjust as needed.");
    } catch (error) {
      console.error("Complete auto-fill error:", error);
      toast.error(error instanceof Error ? error.message : "Failed to auto-fill fields");
    } finally {
      setIsAutoFilling(false);
    }
  };

  // Check for duplicate JSON
  const checkDuplicate = async (jsonContent: string) => {
    if (!jsonContent || jsonContent.trim() === "{}" || jsonContent.trim() === "") {
      setDuplicateWarning(null)
      return
    }

    // Don't check if it's the same as initial data (editing existing workflow)
    if (initialData && JSON.stringify(initialData.workflowJson, null, 2) === jsonContent) {
      return
    }

    setIsCheckingDuplicate(true)
    setDuplicateWarning(null)

    try {
      const response = await fetch("/api/workflows/check-duplicate", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ workflowJson: jsonContent }),
      })

      const data = await response.json()

      if (data.exists && data.workflow) {
        // If editing, check if the found workflow is NOT the current one
        if (!initialData || initialData.id !== data.workflow.id) {
          setDuplicateWarning(data.workflow)
          toast.error("This workflow JSON already exists in the database!")
        }
      }
    } catch (error) {
      console.error("Failed to check duplicate:", error)
    } finally {
      setIsCheckingDuplicate(false)
    }
  }

  // Form submission
  const onSubmit: SubmitHandler<WorkflowFormValues> = async (data) => {
    if (duplicateWarning) {
      toast.error(`Cannot save: Duplicate workflow JSON detected (${duplicateWarning.name})`)
      return
    }

    setIsLoading(true)

    try {
      // Parse JSON
      let parsedJson
      try {
        parsedJson = typeof data.workflowJson === "string" ? JSON.parse(data.workflowJson) : data.workflowJson
      } catch {
        toast.error("Invalid workflow JSON")
        setIsLoading(false)
        return
      }

      const payload = {
        ...data,
        workflowJson: parsedJson,
      }

      const url = initialData ? `/api/workflows/${initialData.id}` : "/api/workflows"
      const method = initialData ? "PUT" : "POST"

      const response = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      })

      if (!response.ok) {
        const errorData = await response.json()
        throw new Error(errorData.error || "Failed to save workflow")
      }

      toast.success(initialData ? "Workflow updated successfully" : "Workflow created successfully")
      router.push("/admin/workflows")
      router.refresh()
    } catch (error) {
      console.error(error)
      toast.error(error instanceof Error ? error.message : "Something went wrong")
    } finally {
      setIsLoading(false)
    }
  }

  return (
    <form onSubmit={handleSubmit(onSubmit)} className="space-y-8">
      {/* Basic Information */}
      <Card>
        <CardHeader>
          <CardTitle>Basic Information</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="name">
                Name <span className="text-red-500">*</span>
              </Label>
              <div className="flex items-start gap-2">
                <Input id="name" {...register("name")} placeholder="Email Newsletter Automation" className="flex-1" />
                <AIButton
                  value={watch("name")}
                  onGenerate={(content) => setValue("name", content)}
                  fieldType="name"
                />
              </div>
              {errors.name && <p className="text-sm text-red-500">{errors.name.message}</p>}
            </div>

            <div className="space-y-2">
              <Label htmlFor="slug">
                Slug <span className="text-red-500">*</span>
              </Label>
              <Input id="slug" {...register("slug")} placeholder="email-newsletter-automation" />
              {errors.slug && <p className="text-sm text-red-500">{errors.slug.message}</p>}
            </div>
          </div>

          <div className="space-y-2">
            <div className="flex items-center justify-between mb-2">
              <Label htmlFor="description">
                Description <span className="text-red-500">*</span>
              </Label>
              <AIButton
                value={watch("description")}
                onGenerate={(content) => setValue("description", content)}
                fieldType="description"
              />
            </div>
            <RichTextEditor
              value={watch("description")}
              onChange={(content) => setValue("description", content)}
              placeholder="Describe what this workflow does..."
              error={errors.description?.message}
            />
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className="space-y-2">
              <Label htmlFor="icon">Icon (Emoji)</Label>
              <Input id="icon" {...register("icon")} placeholder="📧" maxLength={2} />
            </div>

            <div className="space-y-2">
              <Label htmlFor="nodeCount">Node Count</Label>
              <Input
                id="nodeCount"
                type="number"
                {...register("nodeCount", { valueAsNumber: true })}
                placeholder="0"
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="difficulty">
                Difficulty <span className="text-red-500">*</span>
              </Label>
              <Select onValueChange={(value) => setValue("difficulty", value as any)} defaultValue={watch("difficulty")}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="BEGINNER">Beginner</SelectItem>
                  <SelectItem value="INTERMEDIATE">Intermediate</SelectItem>
                  <SelectItem value="ADVANCED">Advanced</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="videoUrl">Video URL (Optional)</Label>
              <Input id="videoUrl" {...register("videoUrl")} placeholder="https://youtube.com/watch?v=..." />
              {errors.videoUrl && <p className="text-sm text-red-500">{errors.videoUrl.message}</p>}
              <p className="text-xs text-muted-foreground">YouTube, Loom, or other video platforms</p>
            </div>

            <div className="space-y-2">
              <Label htmlFor="documentLink">Document Link (Optional)</Label>
              <Input id="documentLink" {...register("documentLink")} placeholder="https://docs.google.com/..." />
              {errors.documentLink && <p className="text-sm text-red-500">{errors.documentLink.message}</p>}
