interface WorkflowVisualizerProps {
  workflowJson: any;
  className?: string;
  miniMode?: boolean;
}

export default function WorkflowVisualizer({
  workflowJson,
  className = "",
  miniMode = false,
}: WorkflowVisualizerProps) {
  // Parse n8n workflow JSON and convert to React Flow format
  const { initialNodes, initialEdges } = useMemo(() => {
    if (!workflowJson || !workflowJson.nodes) {
      return { initialNodes: [], initialEdges: [] };
    }

    const nodes: Node[] = workflowJson.nodes.map((node: any, index: number) => {
      const position = node.position || [index * 350, index * 150];

      return {
        id: node.name || `node-${index}`,
        type: "custom",
        position: {
          x: Array.isArray(position) ? position[0] : position.x || index * 350,
          y: Array.isArray(position) ? position[1] : position.y || index * 150,
        },
        data: {
          label: node.name,
          type: node.type,
          notes: node.notes,
          disabled: node.disabled,
          parameters: node.parameters,
        },
      };
    });

    const edges: Edge[] = [];

    // Parse connections from n8n format
    if (workflowJson.connections) {
      Object.keys(workflowJson.connections).forEach((sourceNode) => {
        const connections = workflowJson.connections[sourceNode];

        Object.keys(connections).forEach((outputType) => {
          const outputs = connections[outputType];

          outputs.forEach((outputConnections: any[], outputIndex: number) => {
            outputConnections.forEach((connection: any, connIndex: number) => {
              edges.push({
                id: `${sourceNode}-${connection.node}-${outputIndex}-${connIndex}`,
                source: sourceNode,
                target: connection.node,
                type: "smoothstep",
                animated: true,
                style: {
                  stroke: "hsl(var(--primary))",
                  strokeWidth: 2,
                },
                markerEnd: {
                  type: MarkerType.ArrowClosed,
                  color: "hsl(var(--primary))",
                  width: 20,
                  height: 20,
                },
              });
            });
          });
        });
      });
    }

    return { initialNodes: nodes, initialEdges: edges };
  }, [workflowJson]);

  const [nodes, setNodes, onNodesChange] = useNodesState(initialNodes);
  const [edges, setEdges, onEdgesChange] = useEdgesState(initialEdges);

  const height = miniMode ? "300px" : "600px";

  if (!workflowJson || !workflowJson.nodes || workflowJson.nodes.length === 0) {
    return (
      <div
        className={`border-2 border-border bg-muted/30 flex items-center justify-center font-mono text-muted-foreground ${className}`}
        style={{ height }}
      >
        NO WORKFLOW DATA AVAILABLE
      </div>
    );
  }

  return (
    <div className={`border-2 border-border bg-background ${className}`} style={{ height }}>
      <ReactFlow
        nodes={nodes}
        edges={edges}
        onNodesChange={onNodesChange}
        onEdgesChange={onEdgesChange}
        nodeTypes={nodeTypes}
        fitView
        fitViewOptions={{
          padding: 0.3,
          minZoom: 0.5,
          maxZoom: 1.5,
        }}
        attributionPosition="bottom-left"
        minZoom={0.1}
        maxZoom={2}
        defaultEdgeOptions={{
          type: "smoothstep",
          animated: true,
          style: {
            stroke: "hsl(var(--primary))",
            strokeWidth: 2,
          },
        }}
        proOptions={{ hideAttribution: true }}
      >
        <Background
          variant={BackgroundVariant.Dots}
          gap={16}
          size={1}
          color="hsl(var(--border))"
        />
        {!miniMode && (
          <>
            <Controls
              className="border-2 border-border bg-background [&_button]:font-mono"
              showInteractive={false}
            />
            <MiniMap
              className="border-2 border-border bg-background"
              nodeColor={(node) => {
                const type = node.data?.type?.toLowerCase() || "";
                if (type.includes("trigger")) return "hsl(var(--primary))";
                if (type.includes("http")) return "rgb(59, 130, 246)";
                if (type.includes("database")) return "rgb(34, 197, 94)";
                if (type.includes("email")) return "rgb(168, 85, 247)";
                if (type.includes("code")) return "rgb(249, 115, 22)";
                return "hsl(var(--muted-foreground))";
              }}
              maskColor="hsl(var(--muted) / 0.8)"
              style={{
                backgroundColor: "hsl(var(--background))",
              }}
            />
            <Panel position="top-left" className="bg-background border-2 border-border p-2">
              <div className="font-mono text-xs font-bold text-foreground uppercase">
                WORKFLOW PREVIEW
              </div>
              <div className="font-mono text-xs text-muted-foreground">
                {nodes.length} nodes • {edges.length} connections
              </div>
            </Panel>
          </>
        )}
      </ReactFlow>
    </div>
  );
}

"use client"

// Inspired by react-hot-toast library
import * as React from "react"

import type {
  ToastActionElement,
  ToastProps,
} from "@/components/ui/toast"

const TOAST_LIMIT = 1
const TOAST_REMOVE_DELAY = 1000000

type ToasterToast = ToastProps & {
  id: string
  title?: React.ReactNode
  description?: React.ReactNode
  action?: ToastActionElement
}

const actionTypes = {
  ADD_TOAST: "ADD_TOAST",
  UPDATE_TOAST: "UPDATE_TOAST",
  DISMISS_TOAST: "DISMISS_TOAST",
  REMOVE_TOAST: "REMOVE_TOAST",
} as const

let count = 0

function genId() {
  count = (count + 1) % Number.MAX_SAFE_INTEGER
  return count.toString()
}

type ActionType = typeof actionTypes

type Action =
  | {
      type: ActionType["ADD_TOAST"]
      toast: ToasterToast
    }
  | {
      type: ActionType["UPDATE_TOAST"]
      toast: Partial<ToasterToast>
    }
  | {
      type: ActionType["DISMISS_TOAST"]
      toastId?: ToasterToast["id"]
    }
  | {
      type: ActionType["REMOVE_TOAST"]
      toastId?: ToasterToast["id"]
    }

interface State {
  toasts: ToasterToast[]
}

const toastTimeouts = new Map<string, ReturnType<typeof setTimeout>>()

const addToRemoveQueue = (toastId: string) => {
  if (toastTimeouts.has(toastId)) {
    return
  }

  const timeout = setTimeout(() => {
    toastTimeouts.delete(toastId)
    dispatch({
      type: "REMOVE_TOAST",
      toastId: toastId,
    })
  }, TOAST_REMOVE_DELAY)

  toastTimeouts.set(toastId, timeout)
}

export const reducer = (state: State, action: Action): State => {
  switch (action.type) {
    case "ADD_TOAST":
      return {
        ...state,
        toasts: [action.toast, ...state.toasts].slice(0, TOAST_LIMIT),
      }

    case "UPDATE_TOAST":
      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === action.toast.id ? { ...t, ...action.toast } : t
        ),
      }

    case "DISMISS_TOAST": {
      const { toastId } = action

      // ! Side effects ! - This could be extracted into a dismissToast() action,
      // but I'll keep it here for simplicity
      if (toastId) {
        addToRemoveQueue(toastId)
      } else {
        state.toasts.forEach((toast) => {
          addToRemoveQueue(toast.id)
        })
      }

      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === toastId || toastId === undefined
            ? {
                ...t,
                open: false,
              }
            : t
        ),
      }
    }
    case "REMOVE_TOAST":
      if (action.toastId === undefined) {
        return {
          ...state,
          toasts: [],
        }
      }
      return {
        ...state,
        toasts: state.toasts.filter((t) => t.id !== action.toastId),
      }
  }
}

const listeners: Array<(state: State) => void> = []

let memoryState: State = { toasts: [] }

function dispatch(action: Action) {
  memoryState = reducer(memoryState, action)
  listeners.forEach((listener) => {
    listener(memoryState)
  })
}

type Toast = Omit<ToasterToast, "id">

function toast({ ...props }: Toast) {
  const id = genId()

  const update = (props: ToasterToast) =>
    dispatch({
      type: "UPDATE_TOAST",
      toast: { ...props, id },
    })
  const dismiss = () => dispatch({ type: "DISMISS_TOAST", toastId: id })

  dispatch({
    type: "ADD_TOAST",
    toast: {
      ...props,
      id,
      open: true,
      onOpenChange: (open) => {
        if (!open) dismiss()
      },
    },
  })

  return {
    id: id,
    dismiss,
    update,
  }
}

function useToast() {
  const [state, setState] = React.useState<State>(memoryState)

  React.useEffect(() => {
    listeners.push(setState)
    return () => {
      const index = listeners.indexOf(setState)
      if (index > -1) {
        listeners.splice(index, 1)
      }
    }
  }, [state])

  return {
    ...state,
    toast,
    dismiss: (toastId?: string) => dispatch({ type: "DISMISS_TOAST", toastId }),
  }
}

export { useToast, toast }

import { GoogleGenerativeAI } from "@google/generative-ai";
import Groq from "groq-sdk";
import { prisma } from "@/lib/prisma";

export type AIProvider = "gemini" | "groq";

interface AIContentOptions {
    systemPrompt?: string;
    temperature?: number;
    jsonMode?: boolean;
}

export async function getActiveProvider(): Promise<AIProvider> {
    try {
        const setting = await prisma.systemSetting.findUnique({
            where: { key: "ai_provider" },
        });

        if (setting?.value) {
            return setting.value as AIProvider;
        }
    } catch (error) {
        console.warn("Failed to fetch AI provider setting, falling back to defaults", error);
    }

    // Default priority: Groq -> Gemini
    if (process.env.GROQ_API_KEY) return "groq";
    return "gemini";
}

export async function generateAIContent(prompt: string, options: AIContentOptions = {}, apiKey?: string): Promise<string> {
    const provider = await getActiveProvider();

    if (provider === "groq") {
        return generateGroqContent(prompt, options, apiKey);
    } else {
        return generateGeminiContent(prompt, options, apiKey);
    }
}

async function generateGroqContent(prompt: string, options: AIContentOptions, apiKey?: string): Promise<string> {
    const key = apiKey || process.env.GROQ_API_KEY;
    if (!key) {
        throw new Error("Missing GROQ_API_KEY");
    }

    const groq = new Groq({ apiKey: key });

    const messages: any[] = [];

    if (options.systemPrompt) {
        messages.push({ role: "system", content: options.systemPrompt });
    }

    messages.push({ role: "user", content: prompt });

    const completion = await groq.chat.completions.create({
        messages,
        model: "llama-3.3-70b-versatile", // Using a capable model
        temperature: options.temperature ?? 0.7,
        response_format: options.jsonMode ? { type: "json_object" } : undefined,
    });

    return completion.choices[0]?.message?.content || "";
}

async function generateGeminiContent(prompt: string, options: AIContentOptions, apiKey?: string): Promise<string> {
    const key = apiKey || process.env.GEMINI_API_KEY;
    if (!key) {
        throw new Error("Missing GEMINI_API_KEY");
    }

    const genAI = new GoogleGenerativeAI(key);
    const model = genAI.getGenerativeModel({
        model: "gemini-2.0-flash-exp",
        generationConfig: {
            responseMimeType: options.jsonMode ? "application/json" : "text/plain",
        }
    });

    let fullPrompt = prompt;
    if (options.systemPrompt) {
        // Gemini doesn't have a strict system prompt in the same way as OpenAI/Groq in the simple API, 
        // but we can prepend it.
        // Actually, newer Gemini models support systemInstruction.
        // For now, prepending is safe or using systemInstruction if available in the SDK version.
        // Let's prepend for compatibility or check SDK version. 
        // The installed version is ^0.24.1 which supports systemInstruction.
        // But let's stick to prepending for now to be safe with existing logic patterns unless we update instantiation.
        fullPrompt = `${options.systemPrompt}\n\nUser: ${prompt}`;
    }

    const result = await model.generateContent(fullPrompt);
    return result.response.text();
}

